\set ON_ERROR_STOP on
select relrowsecurity and not has_table_privilege('anon','public.explanation_figure_candidates','select') and not has_table_privilege('authenticated','public.explanation_figure_candidates','update') and not has_function_privilege('authenticated','public.review_explanation_figure(uuid,text,uuid,boolean,text,text,text,bytea)','execute') and has_function_privilege('service_role','public.review_explanation_figure(uuid,text,uuid,boolean,text,text,text,bytea)','execute') as privileges_pass from pg_class where oid='public.explanation_figure_candidates'::regclass;
set role service_role;
insert into public.explanation_figure_candidates(id,question_id,explanation_sha256,image_sha256,image_mime,image_bytes,source_url,license_url,license,attribution,section_title) values ('00000000-0000-4000-8000-000000000001','Q1',repeat('a',64),repeat('b',64),'image/png',decode('89504e470d0a1a0a','hex'),'https://commons.wikimedia.org/wiki/File:x','https://creativecommons.org/licenses/by/4.0/','CC BY 4.0','author','section');
select public.review_explanation_figure('00000000-0000-4000-8000-000000000001','approved','00000000-0000-4000-8000-000000000002',false,'saved text',repeat('a',64),repeat('b',64),decode('89504e470d0a1a0a','hex'))='invalid' as no_visual_denied;
select public.review_explanation_figure('00000000-0000-4000-8000-000000000001','approved','00000000-0000-4000-8000-000000000002',true,'changed text',repeat('a',64),repeat('b',64),decode('89504e470d0a1a0a','hex'))='stale' as stale_denied;
select public.review_explanation_figure('00000000-0000-4000-8000-000000000001','approved','00000000-0000-4000-8000-000000000002',true,'saved text',repeat('a',64),repeat('b',64),decode('89504e470d0a1a0b','hex'))='conflict' as tamper_denied;
select public.review_explanation_figure('00000000-0000-4000-8000-000000000001','approved','00000000-0000-4000-8000-000000000002',true,'saved text',repeat('a',64),repeat('b',64),decode('89504e470d0a1a0a','hex'))='approved' as approve_pass;
select public.review_explanation_figure('00000000-0000-4000-8000-000000000001','approved','00000000-0000-4000-8000-000000000002',true,'saved text',repeat('a',64),repeat('b',64),decode('89504e470d0a1a0a','hex'))='not_pending' as repeated_denied;
